/*
 * A386183  Primes having only {3, 5, 8, 9} as digits.
 * https://oeis.org/A386183
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   not stated
 * Range:     u8 n <= 6, u16 n <= 105, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 64 terms through n = 9984 (2026-11-03)
 * Helpers:   is_prime_u128, is_prime_u64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: primes having only {3,5,8,9} as digits – generated by brute‑force search */

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdlib.h>
#include <limits.h>
#include "../utils/is_prime_u128.h"
#include "../utils/is_prime_u64.h"

/* -----------------  Generic primality test ------------------------ */
static bool isPrimeGeneric(seq_t n)
{
    /* all seq_t are unsigned; use the smallest type that fits */
    if ((seq_t)(ULLONG_MAX) >= n) {
        return is_prime_u64((uint64_t)n);
    }
#if defined(__SIZEOF_INT128__)
    return is_prime_u128((__uint128_t)n);
#else
    /* fallback: if seq_t > 64‑bit but no 128‑bit support,
       order the test as simple trial division up to sqrt */
    seq_t limit = 0;
    for (seq_t i = 2; i*i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
#endif
}

static bool generate(idx_t target, idx_t len, seq_t cur,
                     idx_t *cnt, seq_t *ret, const int digits[4])
{
    if (len == 0) {
        if (isPrimeGeneric(cur)) {
            ++(*cnt);
            if (*cnt == target) {
                *ret = cur;
                return true;
            }
        }
        return false;
    }
    for (int i = 0; i < 4; ++i) {
        seq_t next = cur * (seq_t)10 + (seq_t)digits[i];
        if (generate(target, len - 1, next, cnt, ret, digits))
            return true;
    }
    return false;
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0; /* undefined for offset < 1 */

    static const int digits[4] = {3, 5, 8, 9};
    idx_t found = 0;
    seq_t result = 0;

    for (idx_t len = 1; ; ++len) {
        if (generate(n, len, (seq_t)0, &found, &result, digits))
            break;
    }
    return result;
}
